import{_ as a,o as t,c as i,a5 as r}from"./chunks/framework.BrSBneze.js";const m=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/quick-start.md","filePath":"getting-started/quick-start.md","lastUpdated":1788882780000}'),o={name:"getting-started/quick-start.md"};function n(l,e,s,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Build and evaluate the printed board, or load the articulated models in a simulator.</p><h2 id="build-the-physical-benchmark" tabindex="-1">Build the physical benchmark <a class="header-anchor" href="#build-the-physical-benchmark" aria-label="Permalink to &quot;Build the physical benchmark&quot;">​</a></h2><ol><li>Review the <a href="/hiveboard-docs/hardware/printing">printing requirements</a>.</li><li>Print one base cell and one attachment to check the press fit.</li><li>Print and <a href="/hiveboard-docs/hardware/assembly">assemble the full benchmark</a>.</li><li>Review all 13 conditions in the <a href="/hiveboard-docs/hardware/modules">module reference</a>, including both ball-valve configurations.</li><li>Follow the <a href="/hiveboard-docs/benchmark/protocol">evaluation protocol</a>.</li><li>Record five trials per condition with the <a href="/hiveboard-docs/benchmark/evaluation-runner">Evaluation Runner</a> or <a href="/hiveboard-docs/benchmark/logging">CSV or XLSX template</a>.</li></ol><h2 id="evaluate-an-existing-board" tabindex="-1">Evaluate an existing board <a class="header-anchor" href="#evaluate-an-existing-board" aria-label="Permalink to &quot;Evaluate an existing board&quot;">​</a></h2><ol><li>Check every attachment for damage, free motion, and secure seating.</li><li>Fix the base to a rigid surface and document its orientation.</li><li>Read the task-specific success criteria and timeouts.</li><li>Complete familiarization before recording.</li><li>Run five recorded trials for all 13 conditions. Record every trial with an external camera.</li><li>Check the trial entries and include the setup photograph, platform description, and recordings with the results.</li></ol><p>Go directly to the <a href="/hiveboard-docs/benchmark/protocol">evaluation protocol</a>.</p><h2 id="work-in-simulation" tabindex="-1">Work in simulation <a class="header-anchor" href="#work-in-simulation" aria-label="Permalink to &quot;Work in simulation&quot;">​</a></h2><ul><li><strong>Articulated assets:</strong> use the URDF or USD files from the main repository in your own simulator or robotics stack.</li><li><strong>Isaac Lab environment:</strong> use the dedicated repository to train and evaluate policies in Isaac Lab.</li></ul><p>Read <a href="/hiveboard-docs/simulation/assets">Simulation assets</a> before selecting the implementation. The physical and simulation parameters should be reported separately because friction, contact, and press-fit behavior vary between printed instances.</p><h2 id="minimum-reporting-package" tabindex="-1">Minimum reporting package <a class="header-anchor" href="#minimum-reporting-package" aria-label="Permalink to &quot;Minimum reporting package&quot;">​</a></h2><p>A physical benchmark result should identify:</p><ul><li>the HiveBoard release or commit;</li><li>printer, material, and any post-processing;</li><li>board mounting orientation;</li><li>robot and end-effector;</li><li>control interface or policy;</li><li>the completed trial log; and</li><li>any broken, replaced, or reseated parts.</li></ul><p>Include <code>setup.jpg</code> and all 65 trial recordings. The runner exports the trial log and platform description, and lists the required video filenames. Incomplete sessions can be saved and resumed; a submission must contain all 65 trials.</p>',14)])])}const p=a(o,[["render",n]]);export{m as __pageData,p as default};
